// Normalize whatever the Error Trigger received into a small alert record.
const data = $input.first().json || {};
const execution = data.execution || {};
const alert = {
  failedWorkflow: data.workflow?.name ?? 'unknown workflow',
  failedNode: execution.lastNodeExecuted ?? 'unknown node',
  errorMessage: execution.error?.message ?? String(execution.error ?? 'unknown error'),
  executionUrl: execution.url ?? null,
  occurredAt: new Date().toISOString(),
};
return [{ json: alert }];

// SAFE DEFAULT: log the alert. Swap for a real pager/email by enabling the
// 'Email Alert (disabled)' node with a genuine credential.
for (const item of $input.all()) {
  console.error('[LendLoop alert] Workflow failure:', JSON.stringify(item.json));
}
return $input.all();
